#!/usr/bin/env perl

use strict;
use warnings;

# parse_var_path.pl

# Parse the AT field (extracted with bcftools query) from a vcf generated by cactus to find which nodes to check to distinguish between alleles at variant sites.
# This version works only with biallelic variants, and make sure to remove unused alleles
# Command to get input for this script from an input with 2 samples (i.e. 4 haplotypes)
#	- all haplotypes called (no missing)
#	- only one alt allele (i.e. biallelic)
#	- sites with no more than 3 non-ref alleles (to exclude sites where all haplotypes are the same and the only difference is from the reference)
# bcftools view -g ^miss -m2 -M2 --max-ac 3 <input.vcf.gz> | bcftools query -f '%ID\t%CHROM\t%POS\t%REF\t%ALT\t%INFO/AT\t[%GT\t]\n' > <output.txt>


# Details:
# Classify variants based on the difference between paths. Aim is to separate based on how you would distinguish between reads from each haplotype
# If a variant contains nodes repeated either within or between paths, it will be classed as 'complex' and not processed further.
# Possibilities:
	# Same number of nodes, different central node(s) -- SNP (3 nodes each, both alleles are 1 bp), MNP (both alleles are the same number of bases >1) or unequal substitution*
	# One allele has two nodes, the other has those two with others between -- indel
		# Special case (not output): central nodes are the same as flanking -- duplication
		# Special case (not output): central nodes are out of sequence -- possible translocation
		
	# Same nodes, one(s) in the middle have different signs -- inversion (not output)
	# Different numbers of nodes, different central nodes, no repeats -- unequal substitution
	# Other duplications (not output)
	# More complex variants (not output)
# N.B. Just because an indel doesn't have any repeated nodes doesn't mean it has no repeats, or is not a change in the number of units in a repeat region.f
# *Made up the category of 'unequal substitution' to cover cases where the alleles are different length and you can't get to allele 2 by a single insertion or deletion to allele 1, e.g. allele 1 is TA, allele 2 is TGTAAGAC. Could have arisen in various ways, this is just a convenient term.
# Also assume that all the alleles' paths *must* start and end with the same node (by definition)
# If this is not the case, put in the 'complex' pile.

# Output in this version for indels, SNPs, MNPs, unequal subs (single format for all variants):
# refchr, ID, pos, variant type, node range, paths, genotypes
# The node range column is only filled properly for indels, for everything else it's NA
# The paths column for indles is the unique paths (and if an allele has multiple unique paths these will be separated by | (for using in regex), and the two alleles will be separated by a comma). For others it is the paths from the AT field
# For other variant types, just print the input line to the 'complex' output


my $outname = shift;	# for name of output in cwd (no directories)
my $samplenames = shift;	# comma-separated list of sample names to use for heading - same order as vcf
my $debug = shift;

# These are for output to process further
open (OUT, ">variants.$outname.txt");

# This is just for reference and contain the input lines
open (OUT_C, ">complex.$outname.txt");

if ($debug)	{
	open (OUT_DE, ">debug.$outname.txt");
}

$samplenames =~ s/\,/\t/g;
print OUT "RefChr\tID\tRefPos\tVarType\tRange\tAllelePaths\t$samplenames\n";

$samplenames =~ s/\,/\t/g;
my @samples = split(/\,/, $samplenames);
my $s_header = join

my $indels = 0;
my $snps = 0;
my $mnps = 0;
my $unsub = 0;

VARIANT:
while (<STDIN>)	{
	chomp;
	my @info = split(/\s+/, $_);
	my @alls = split(/\,/, $info[5]);
	if ($info[4] =~ /\,/)	{
		die "Script only works for biallelic variants, this line is not:\n$_\n";
	}
	my @seqs = @info[3..4];
 
	my $genotypes = join("\t", splice(@info, 6));	# removes GTs from info but this is ok
	
	# Lists of ref then alt direction+node, node, direction, in same order for each (i.e. ref node 1 is first element of first list in all three arrays)
	my @paths;	# nodes plus directions
	my @nodes;
	my @dirs;
	
	for my $ind (0 .. 1)	{
		foreach my $node (split(/(?=[<>])/, $alls[$ind]))	{
			push (@{$paths[$ind]}, $node);
			my @ar = split (/(?<=[<>])/, $node);
			push (@{$dirs[$ind]}, $ar[0]);
			push (@{$nodes[$ind]}, $ar[1]);
		}
	}
	
	# Double check that the start and end nodes are the same for both alleles
	unless ((${$paths[0]}[0] eq ${$paths[1]}[0]) && (${$paths[0]}[-1] eq ${$paths[1]}[-1])) {
		die "Problem with path definition: $_\n";
	}
	
	# Find out how many nodes are in each path and check that both have at least two
	my @counts = (scalar @{$paths[0]}, scalar @{$paths[1]});
	my @sorted = sort {$a <=> $b} @counts;
	my $twonodes = 0;
	if ($sorted[0] < 2)	{
		die "One allele has fewer than two nodes:\n$_\n";
	}
	if ($sorted[0] == 2) 	{
		$twonodes = 1
	}
	
	# Check if any nodes are repeated within a path and skip if so
	my ($int_repeats1) = check_internal_repeats($nodes[0]);
	my ($int_repeats2) = check_internal_repeats($nodes[1]);
	if ($int_repeats1 || $int_repeats2)	{
		print OUT_C "$_\n";
		if ($debug)	{
			print OUT_DE "InternalRepeats\t$_\n";
		}
		next VARIANT;
	}

	# Check whether any of the non-flanking nodes are shared between paths, or if the flanking nodes are repeated in the middle. If yes, skip.
	my $repeat_between = check_repeats($nodes[0], $nodes[1], $twonodes);
	if ($repeat_between)	{
		print OUT_C "$_\n";
		if ($debug)	{
			print OUT_DE "BetweenRepeats\t$_\n";
		}
		next VARIANT;
	}
	
	# Check whether the nodes make a sequence (if not, carry on with checking and report this along with variant type)
	my ($pass, $start, $end) = check_node_sequence($nodes[0], $nodes[1], \@alls);
	
	## Variant classification
	# Start with variants where both alleles have the same number of nodes
	if ($counts[0] == $counts[1])	{
		if ($twonodes)	{	# This shouldn't happen
			warn "Problem: both haplotypes have exactly two nodes\n$_\n";
			next VARIANT;
		}
		unless ($pass)	{
			print OUT_C "$_\n";
			if ($debug)	{
				print OUT_DE "MNP_fail\t$_\n";
			}
			next VARIANT;
		}
	
		# Check whether both alleles are the same length (i.e. number of bases, not number of nodes as in @counts)
		my $len1 = length $seqs[0];
		my $len2 = length $seqs[1];
	
		if ($len1 == $len2)	{
			if ($len1 == 1)	{
				# Variant is a SNP
				# If there are >3 nodes, something is not as expected.
				unless ($counts[0] == 3)	{
					warn "Problem: SNP has more than 3 nodes\n$_\n";
					next VARIANT;
				}
				print OUT "$info[1]\t$info[0]\t$info[2]\tsnp\tNA\t$info[5]\t$genotypes\n";
				$snps ++;
				if ($debug)	{
					print OUT_DE "SNP\t$_\n";
				}
				next VARIANT;
			}
			else	{
				# variant is a multi-nucleotide polymorphism
				print OUT "$info[1]\t$info[0]\t$info[2]\tmnp\tNA\t$info[5]\t$genotypes\n";
				$mnps ++;
				if ($debug)	{
					print OUT_DE "MNP\t$_\n";
				}
				next VARIANT;
			}
		}
		else	{
			# Variant is more complex ('unequal substitution')
			# If everything is working as expected, both alleles should be >1 bp (otherwise they should be coming up as indels). Check this.
			if (($len1 == 1) || ($len2 == 1))	{
				warn "Problem: variant should be indel?\n$_\n";
			}
			print OUT "$info[1]\t$info[0]\t$info[2]\tuneqsub\tNA\t$info[5]\t$genotypes\n";
			$unsub ++;
			if ($debug)	{
				print OUT_DE "unsub\t$_\n";
			}
			next VARIANT;
		}
	}

	# If exactly two nodes in one of the paths, then variant can be processed as a straightforward indel -- one allele just has something inserted between two nodes that are in both
	# Get the paths that distinguish between alleles -- for the allele with the insertion this is every node except the flanking ones, for the other allele it's the full path (i.e. the two flanking alleles together)
	elsif ($twonodes)	{
		unless ($pass)	{
			print OUT_C "$_\n";
			if ($debug)	{
				print OUT_DE "indel_fail\t$_\n";
			}
			next VARIANT;
		}
		
		# Find which allele has the insert
		my $which;
		if ($counts[0] == 2)	{
			$which = 1;	# alt has insert
		}
		elsif ($counts[1] == 2)	{
			$which = 0;
		}
		else	{
			die
		}
		my @checknodes = @alls;
		$checknodes[$which] = join('|', splice(@{$paths[$which]}, 1, -1));	# remove flanking alleles and join nodes into string for regex
		print OUT "$info[1]\t$info[0]\t$info[2]\tindel\t$start:$end\t", join (',', @checknodes), "\t$genotypes\n";
		$indels ++;
		if ($debug)	{
			print OUT_DE "indel\t$_\n";
		}
		next VARIANT;
	}
	# Otherwise (neither path has exactly two nodes, but there are no repeated nodes), class as unequal substitution
	else	{
		unless ($pass)	{
			print OUT_C "$_\n";
			if ($debug)	{
				print OUT_DE "indel_fail\t$_\n";
			}
			next VARIANT;
		}
		print OUT "$info[1]\t$info[0]\t$info[2]\tuneqsub\tNA\t$info[5]\t$genotypes\n";
		$unsub ++;
		if ($debug)	{
			print OUT_DE "unsub_long\t$_\n";
		}
		next VARIANT;
	}
}	# end of VARIANT
	
# Subroutine to check for repeated nodes within a path
sub check_internal_repeats	{
	my ($check) = @_;
	my @array = @$check;
	
	my %set1;
	my %repeated;
	# Get the nodes and positions
	for (my $i = 0; $i < @array; $i ++)	{
		$set1{$array[$i]} = $i+1;
	}
	# Go through again and see if the node appears anywhere other than its last noted position. If there is a repeat then only one $i will be there, so one copy will match $i and not trigger 'repeat', but the other copy will not match so will trigger 'repeat'.
	for (my $i = 0; $i < @array; $i ++)	{
		next if ($set1{$array[$i]} == $i+1);
		$repeated{$array[$i]} = 1;
	}
	
	if (scalar keys %repeated)	{
		return (\%repeated);
	}
	else	{
		return (0);
	}
}
	
# Subroutine to check for repeated nodes between two arrays
# Turns out these are very unlikely because of the way the graph is put together
# Check first and last ('flanking') nodes separately as these are expected to be identical in both alleles
sub check_repeats	{
	my ($check1, $check2, $if_twonodes) = @_;
	my @arr1 = @$check1;
	my @arr2 = @$check2;
	
	# Remove the flanking nodes
	my $first1 = shift @arr1;
	my $first2 = shift @arr2;
	my $last1 = pop @arr1;
	my $last2 = pop @arr2;
	# Check there is something left
	unless (($arr1[0] && $arr2[0]) || $if_twonodes)	{
		warn "Arrays too short in repeat checking: $_\n";
		return (0);
	}
	# If both are two nodes, nothing to check so return
	unless ($arr1[0] || $arr2[0])	{
		return (0);
	}

	# Get the non-flanking nodes in path 1
	my %set1;
	my %repeated;
	for (my $i = 0; $i < @arr1; $i ++)	{
		$set1{$arr1[$i]} = 1;
	}
	# Check if any of these are repeated in path 2
	my %set2;
	for (my $i = 0; $i < @arr2; $i ++)	{
		$set2{$arr2[$i]} = 1;	# to check against flanking
		if ($set1{$arr2[$i]})	{
			$repeated{$arr2[$i]} = 1;
		}
	}
	
	# Check if the flanking nodes are repeated in either middle section
	if ($set1{$first1} || $set2{$first1})	{
		$repeated{$first1} = 1;
	}
	if ($set1{$last1} || $set2{$last1})	{
		$repeated{$last1} = 1;
	}
	
	if (scalar keys %repeated)	{
		return (\%repeated);
	}
	else	{
		return (0);
	}
}

# Subroutine to check whether the set of nodes forms a continuous sequence, and return the start and end nodes. Doesn't check if they are in order.
sub check_node_sequence	{
	my ($list1, $list2) = @_;
	my @list = sort {$a <=> $b} (@$list1, @$list2);
	my ($start, $end) = ($list[0], $list[-1]);
	my $fail = 0;
	my @missing;
	for (my $i = 0; $i < @list-1; $i ++)	{
		next if (($list[$i] + 1 == $list[$i+1]) || ($list[$i] == $list[$i+1]));
		my $miss = $list[$i] + 1;
		while ($miss < $list[$i+1])	{
			push (@missing, $miss);
			$miss ++;
		}
		last;
	}
	if ($missing[0])	{
		return (0)
	}
	else	{
		return (1, $start, $end);
	}
}
